    /// The value in the most readable SI-prefixed form of the base unit, in
    /// steps of 1000: the largest unit not exceeding the value (`J/kg`, `kJ/kg`, `MJ/kg`).
    /// Zero, NaN and infinities are shown in the base unit.
    #[inline]
    pub fn auto_unit(self) -> crate::InUnit<T, SpecificEnergyUnit> {
        const SCALE: [(f64, SpecificEnergyUnit); 3] = [
            (1000000.0, SpecificEnergyUnit::MegajoulePerKilogram),
            (1000.0, SpecificEnergyUnit::KilojoulePerKilogram),
            (1.0, SpecificEnergyUnit::JoulePerKilogram),
        ];
        let magnitude = self.0.abs();
        if magnitude == T::from_f64(0.0) || !magnitude.is_finite() {
            return self.in_unit(SpecificEnergyUnit::JoulePerKilogram);
        }
        let mut unit = SCALE[SCALE.len() - 1].1;
        for (factor, candidate) in SCALE {
            if magnitude >= T::from_f64(factor) {
                unit = candidate;
                break;
            }
        }
        self.in_unit(unit)
    }

